#!/usr/bin/env bash
# Deploy f4e10742-bd72-442a-88b0-b1a915a3f51b to Cloudflare
# Generated by aristotle-manager deploy cloudflare

set -euo pipefail

PROJECT_DIR="/home/mdupont/projects/arist/f4e10742-bd72-442a-88b0-b1a915a3f51b"

if [[ ! -d "$PROJECT_DIR" ]]; then
  echo "ERROR: project directory not found: $PROJECT_DIR" >&2
  exit 1
fi

PROJECT_UUID="f4e10742-bd72-442a-88b0-b1a915a3f51b"
PNAME="$(echo "$PROJECT_UUID" | cut -c1-12)"

if [ "$#" -gt 0 ] && [[ "$1" == "--project-name" ]]; then
  PNAME="$2"
  shift 2
fi

# Detect project capabilities
HAS_STATIC=false
HAS_WORKER=false

if [[ -d "$PROJECT_DIR/www" ]]; then
  HAS_STATIC=true
  STATIC_DIR="$PROJECT_DIR/www"
elif [[ -d "$PROJECT_DIR/hodge-vm/www" ]]; then
  HAS_STATIC=true
  STATIC_DIR="$PROJECT_DIR/hodge-vm/www"
elif [[ -f "$PROJECT_DIR/create_static_site.py" ]]; then
  HAS_STATIC=true
  STATIC_DIR="$PROJECT_DIR/www"
fi

WORKER_DIR=""
WORKER_NAME=""
WRANGLER_CFG=""
if [[ -f "$PROJECT_DIR/minilean/edge/cloudflare/wrangler.toml" ]]; then
  WORKER_DIR="$PROJECT_DIR/minilean/edge/cloudflare"
  WORKER_NAME="minilean-mlvm"
  WRANGLER_CFG="$WORKER_DIR/wrangler.toml"
elif [[ -f "$PROJECT_DIR/hodge-vm/dist/wrangler-p2p.toml" ]] && [[ -f "$PROJECT_DIR/hodge-vm/dist/p2p-worker.mjs" ]]; then
  WORKER_DIR="$PROJECT_DIR/hodge-vm/dist"
  WORKER_NAME="hodge-p2p"
  WRANGLER_CFG="$WORKER_DIR/wrangler-p2p.toml"
fi

echo "=== Deploy $PNAME ($PROJECT_UUID) ==="
echo "Static site:   $([[ $HAS_STATIC == true ]] && echo "$STATIC_DIR" || echo "none")"
echo "Worker:        $([[ $HAS_WORKER == true || -n "$WORKER_DIR" ]] && echo "$WORKER_NAME ($WRANGLER_CFG)" || echo "none")"
echo ""

echo "=== Credential Check ==="
echo "Ensure credentials are available via:"
echo "  - SOPS: ~/.config/sops/age/keys.txt + /etc/tracker-vault/secrets/"
echo "  - OR: /run/gui2proof/cloudflare.env"
echo ""

if $HAS_STATIC || [ -n "$WORKER_DIR" ]; then
  echo "=== Deploy ==="
  echo "Run:"
  echo "  /home/mdupont/projects/arist/bin/aristotle-manager deploy cloudflare $PROJECT_UUID"
  echo ""
  echo "Or with flags:"
  if $HAS_STATIC; then
    echo "  /home/mdupont/projects/arist/bin/aristotle-manager deploy cloudflare $PROJECT_UUID --pages"
  fi
  if [ -n "$WORKER_DIR" ]; then
    echo "  /home/mdupont/projects/arist/bin/aristotle-manager deploy cloudflare $PROJECT_UUID --worker"
  fi
  echo ""
  echo "Or for a dry run:"
  echo "  /home/mdupont/projects/arist/bin/aristotle-manager deploy cloudflare $PROJECT_UUID --dry-run"
else
  echo "=== No deploy configuration detected ==="
  echo "This project has no static site (www/) or worker config (wrangler.toml)."
fi
